INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist pytest ein Test-Framework, das speziell für die testgetriebene Entwicklung (TDD) in Python entwickelt wurde?', 2, '[{"text": "Ja", "correct": true, "because": "pytest unterstützt TDD in Python effektiv"}, {"text": "Nein", "correct": false, "because": "Entwickelt für Python-Tests inkl. TDD"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann pytest ohne zusätzliche Plugins für komplexe Testfälle in TDD verwendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "pytest ist flexibel und funktioniert out-of-the-box"}, {"text": "Nein", "correct": false, "because": "Keine Plugins zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen pytest-Tests in TDD explizite Assertions enthalten, um Fehler zu erkennen?', 2, '[{"text": "Ja", "correct": true, "because": "Assertions sind nötig für Überprüfung"}, {"text": "Nein", "correct": false, "because": "Assertions definieren Erwartungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können pytest-Tests in TDD auch ohne Python-Entwicklungsumgebung ausgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "pytest erfordert Python"}, {"text": "Ja", "correct": false, "because": "Python-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist pytest in TDD ausschließlich für Unit-Tests geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "pytest unterstützt auch andere Testarten"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktion erfüllt pytest in der testgetriebenen Entwicklung?', 2, '[{"text": "Automatisierte Ausführung von Tests", "correct": true, "because": "Hauptzweck von pytest"}, {"text": "Code-Generierung", "correct": false, "because": "Nicht Aufgabe von pytest"}, {"text": "Laufzeitoptimierung", "correct": false, "because": "Kein Optimierungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature von pytest erleichtert die Testfallerstellung in TDD?', 3, '[{"text": "Einfache Syntax", "correct": true, "because": "Minimale Boilerplate-Code"}, {"text": "Automatische Code-Generierung", "correct": false, "because": "Nicht verfügbar"}, {"text": "Grafische Oberfläche", "correct": false, "because": "CLI-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase des TDD-Zyklus wird durch pytest direkt unterstützt?', 2, '[{"text": "Rot-Phase", "correct": true, "because": "Tests schlagen zunächst fehl"}, {"text": "Grün-Phase", "correct": false, "because": "Nach Korrektur"}, {"text": "Refactor-Phase", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kommando wird verwendet, um pytest-Tests in TDD auszuführen?', 2, '[{"text": "pytest", "correct": true, "because": "Standardbefehl zum Starten"}, {"text": "python -m test", "correct": false, "because": "Nicht pytest-spezifisch"}, {"text": "run-tests", "correct": false, "because": "Kein pytest-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil von pytest ist in TDD besonders nützlich?', 2, '[{"text": "Detaillierte Fehlermeldungen", "correct": true, "because": "Erleichtert Fehlerlokalisierung"}, {"text": "Hohe Laufzeitkosten", "correct": false, "because": "Effizient"}, {"text": "Manuelle Teststeuerung", "correct": false, "because": "Automatisierung zentral"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet pytest für TDD?', 4, '[{"text": "Automatische Testentdeckung", "correct": true, "because": "Findet Tests ohne Konfiguration"}, {"text": "Assertion-Unterstützung", "correct": true, "because": "Überprüft Ergebnisse"}, {"text": "Code-Debugging", "correct": false, "because": "Nicht Hauptfunktion"}, {"text": "Fixtures", "correct": true, "because": "Bereitstellung von Testdaten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt pytest in TDD?', 3, '[{"text": "Schnelle Testausführung", "correct": true, "because": "Fördert Iterationen"}, {"text": "Einfache Testfallerstellung", "correct": true, "because": "Minimale Syntax"}, {"text": "Hoher Speicherbedarf", "correct": false, "because": "Effizient"}, {"text": "Detaillierte Fehlerberichte", "correct": true, "because": "Erleichtert Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche pytest-Features sind für TDD besonders nützlich?', 3, '[{"text": "Fixtures", "correct": true, "because": "Wiederverwendbare Testdaten"}, {"text": "Parametrisierte Tests", "correct": true, "because": "Mehrere Szenarien testen"}, {"text": "Manuelle Teststeuerung", "correct": false, "because": "Automatisierung zentral"}, {"text": "Automatische Testentdeckung", "correct": true, "because": "Findet Tests automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei der Nutzung von pytest in TDD auftreten?', 4, '[{"text": "Lernkurve für Plugins", "correct": true, "because": "Erweiterungen komplex"}, {"text": "Wartung der Test-Suite", "correct": true, "because": "Änderungen nötig"}, {"text": "Keine Integration möglich", "correct": false, "because": "Gut integrierbar"}, {"text": "Komplexität bei großen Projekten", "correct": true, "because": "Viele Tests zu verwalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen pytest zu einem geeigneten Werkzeug für TDD?', 3, '[{"text": "Einfache Syntax", "correct": true, "because": "Erleichtert Testfallerstellung"}, {"text": "Schnelle Testausführung", "correct": true, "because": "Fördert Iterationen"}, {"text": "Hohe Laufzeitkosten", "correct": false, "because": "Effizient"}, {"text": "Flexibilität bei Testarten", "correct": true, "because": "Unit- und mehr"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) pytest ist ein Standardwerkzeug für TDD in Python. b) pytest kann keine Unit-Tests ausführen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "pytest Standard, Unit-Tests möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) pytest erfordert komplexe Konfiguration für TDD. b) pytest unterstützt den Red-Green-Refactor-Zyklus.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Konfiguration minimal, Zyklus unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) pytest beschleunigt die Fehlererkennung in TDD. b) pytest ist für Java-Projekte optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlererkennung schnell, Python-spezifisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) pytest unterstützt Fixtures für wiederverwendbare Testdaten. b) pytest-Tests müssen manuell ausgeführt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fixtures verfügbar, Automatisierung Standard"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) pytest bietet detaillierte Fehlermeldungen in TDD. b) pytest ist für TDD in großen Projekten ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlermeldungen klar, Größe flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
